perfFilterInstrument:
() => {
 const input=document.querySelector('input[placeholder="Filter runs by name"]');
 const links=()=>[...document.querySelectorAll('a[data-testid="run-name-link"]')];
 if(!input||input.value!==''||links().length!==4)throw new Error('Filter precondition failed');
 performance.clearMarks();performance.clearMeasures();
 const before={value:input.value,rows:links().map(el=>({name:el.textContent.trim(),href:el.getAttribute('href')}))};
 let started=false,finished=false;
 const onInput=()=>{if(input.value==='xgboost'&&!started){started=true;performance.mark('filter-start');check();}};
 const observer=new MutationObserver(check);
 function check(){const items=links();if(started&&!finished&&items.length===1&&items[0].textContent.includes('xgboost')){finished=true;observer.disconnect();input.removeEventListener('input',onInput);requestAnimationFrame(()=>requestAnimationFrame(()=>{performance.mark('filter-ready');performance.measure('filter-results','filter-start','filter-ready');}));}}
 input.addEventListener('input',onInput);observer.observe(document.body,{subtree:true,childList:true,characterData:true});
 window.__kfpPerfFilterBefore=before;
 return before;
}

