(kind) => {
 const taskSelector='[data-testid="DagCanvas"] .react-flow__node[data-id="task.chicago-taxi-trips-dataset"]';
 const target=kind==='run-open'?document.querySelector('a[data-testid="run-name-link"][href*="e0115ac1-0479-4194-a22d-01e65e09a32b"]'):document.querySelector(taskSelector);
 if(!target)throw new Error('Navigation target missing: '+kind);
 const predicate=()=>kind==='run-open'?!!document.querySelector(taskSelector):[...document.querySelectorAll('[role="tab"],button')].some(el=>el.textContent.trim()==='Task Details'&&el.getClientRects().length>0&&getComputedStyle(el).visibility!=='hidden');
 if(predicate())throw new Error('Navigation postcondition already present: '+kind);
 let started=false,finished=false;
 function check(){if(started&&!finished&&predicate()){finished=true;observer.disconnect();target.removeEventListener('click',onClick,true);requestAnimationFrame(()=>requestAnimationFrame(()=>{performance.mark(kind+'-ready');performance.measure(kind,kind+'-start',kind+'-ready');}));}}
 const onClick=()=>{if(!started){started=true;performance.mark(kind+'-start');check();}};
 const observer=new MutationObserver(check);
 observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true});
 target.addEventListener('click',onClick,true);
 return {kind,hash:location.hash,target:target.textContent.trim()};
}

